mapper.select:
SELECT * FROM coach_student_matches
WHERE student_id = #{studentId}
  AND coach_id = #{coachId}
  AND delete_flag = 0

mapper.update:
UPDATE coach_student_matches
SET status = #{status}, update_time = NOW()
WHERE student_id = #{studentId}
  AND coach_id = #{coachId}
  AND delete_flag = 0
